export function resolveTheme(id) {
  return themes.find(theme => theme.id === id) ?? themes[0];
}

export function mix(a, b, weight) {
  const rgb = value => value.slice(1).match(/../g).map(channel => parseInt(channel, 16));
  const left = rgb(a), right = rgb(b);
  return '#' + left.map((value, index) => Math.round(value * (1 - weight) + right[index] * weight).toString(16).padStart(2, '0')).join('');
}

export function themeTokens(theme) {
  const bg = theme.background, dark = theme.dark;
  return { bg, panel: mix(bg, '#ffffff', dark ? .045 : .62), ink: dark ? '#f1eee7' : '#252c31',
    muted: dark ? '#b8bdb9' : '#606766', edge: mix(bg, dark ? '#ffffff' : '#252c31', .19),
    mint: theme.accent, gold: dark ? '#d8bd80' : '#826327', wash: mix(bg, theme.accent, dark ? .14 : .12),
    danger: dark ? '#ffb9a8' : '#943c2a', 'action-ink': dark ? '#151a1d' : '#ffffff' };
}
